ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_dev *dev = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!dev)
        return -EINVAL;

    mutex_lock(&dev->mutex);
    spin_lock_irq(&dev->spinlock);

    while (dev->queue_size == 0) {
        if ((file->f_flags & O_NONBLOCK) || (file->f_flags & O_CLOEXEC)) {
            spin_unlock_irq(&dev->spinlock);
            mutex_unlock(&dev->mutex);
            return -EAGAIN;
        }

        ret = wait_event_interruptible(dev->read_wait, dev->queue_size > 0);
        if (ret < 0) {
            spin_unlock_irq(&dev->spinlock);
            mutex_unlock(&dev->mutex);
            return ret;
        }
    }

    while (count > 0 && dev->queue_size > 0) {
        unsigned int chunk_size = min(count, (size_t)dev->sample_size);
        if (copy_to_user(buffer, dev->queue + dev->read_pos, chunk_size)) {
            spin_unlock_irq(&dev->spinlock);
            mutex_unlock(&dev->mutex);
            return -EFAULT;
        }

        dev->read_pos = (dev->read_pos + chunk_size) % dev->buffer_size;
        dev->queue_size -= chunk_size;
        bytes_read += chunk_size;
        count -= chunk_size;
        buffer += chunk_size;
    }

    spin_unlock_irq(&dev->spinlock);
    mutex_unlock(&dev->mutex);

    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    int result;

    mutex_lock(&sound_timer_mutex);
    spin_lock(&sound_timer_spinlock);

    if (sound_timer_queue_empty()) {
        if (file->f_flags & O_NONBLOCK) {
            spin_unlock(&sound_timer_spinlock);
            mutex_unlock(&sound_timer_mutex);
            return -EAGAIN;
        }
        DECLARE_WAITQUEUE(wait, current);
        add_wait_queue(&sound_timer_wait_queue, &wait);
        set_current_state(TASK_INTERRUPTIBLE);

        spin_unlock(&sound_timer_spinlock);
        mutex_unlock(&sound_timer_mutex);

        schedule();

        remove_wait_queue(&sound_timer_wait_queue, &wait);
        if (signal_pending(current)) {
            return -ERESTARTSYS;
        }

        mutex_lock(&sound_timer_mutex);
        spin_lock(&sound_timer_spinlock);
    }

    while (bytes_read < count && !sound_timer_queue_empty()) {
        char data = sound_timer_peek();
        if (copy_to_user(buffer + bytes_read, &data, 1) != 0) {
            spin_unlock(&sound_timer_spinlock);
            mutex_unlock(&sound_timer_mutex);
            return -EFAULT;
        }

        sound_timer_dequeue();
        bytes_read++;
        *offset += 1;
    }

    spin_unlock(&sound_timer_spinlock);
    mutex_unlock(&sound_timer_mutex);

    return bytes_read;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;

    mutex_lock(&device_mutex);
    spin_lock(&device_spinlock);

    if (device_queue_empty) {
        // Wait for data to become available, handling non-blocking and interruptible conditions
        if (wait_for_data() < 0) {
            spin_unlock(&device_spinlock);
            mutex_unlock(&device_mutex);
            return -EINTR;
        }
    }

    if (count > device_data_available) {
        count = device_data_available;
    }

    if (copy_to_user(buffer, device_queue + read_position, count)) {
        spin_unlock(&device_spinlock);
        mutex_unlock(&device_mutex);
        return -EFAULT;
    }

    read_position += count;
    bytes_read = count;
    device_data_available -= count;

    spin_unlock(&device_spinlock);
    mutex_unlock(&device_mutex);

    return bytes_read;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    ssize_t bytes_read = 0;
    int ret;

    spin_lock(&device_spinlock);
    mutex_lock(&device_mutex);

    while (device_queue_empty()) {
        if (file->f_flags & O_NONBLOCK) {
            mutex_unlock(&device_mutex);
            spin_unlock(&device_spinlock);
            return -EAGAIN;
        }

        ret = wait_event_interruptible(device_wait_queue, !device_queue_empty());
        if (ret < 0) {
            mutex_unlock(&device_mutex);
            spin_unlock(&device_spinlock);
            return ret;
        }
    }

    while (bytes_read < count && !device_queue_empty()) {
        char data = device_peek_data();
        ret = copy_to_user(buffer + bytes_read, &data, 1);
        if (ret != 0) {
            mutex_unlock(&device_mutex);
            spin_unlock(&device_spinlock);
            return -EFAULT;
        }
        device_dequeue_data();
        bytes_read++;
    }

    mutex_unlock(&device_mutex);
    spin_unlock(&device_spinlock);
    *offset += bytes_read;

    return bytes_read;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    struct sound_timer_dev *dev = file->private_data;
    struct sound_timer_queue *queue = &dev->queue;

    if (!dev || !queue)
        return -EINVAL;

    if (count == 0)
        return 0;

    spin_lock(&dev->lock);

    while (queue->read_index == queue->write_index) {
        if (file->f_flags & O_NONBLOCK) {
            spin_unlock(&dev->lock);
            return -EAGAIN;
        }

        if (wait_event_interruptible(queue->wait_read, queue->read_index != queue->write_index)) {
            spin_unlock(&dev->lock);
            return -ERESTARTSYS;
        }
    }

    while (bytes_read < count && queue->read_index != queue->write_index) {
        unsigned char data = queue->buffer[queue->read_index];
        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            spin_unlock(&dev->lock);
            return -EFAULT;
        }
        queue->read_index = (queue->read_index + 1) % SOUND_TIMER_BUFFER_SIZE;
        bytes_read++;
    }

    spin_unlock(&dev->lock);
    wake_up_interruptible(&queue->wait_write);

    return bytes_read;
}
